"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.34283",title:"ChronoReplay: One Answer Interface Is Not Enough for Streaming Spatial Intelligence",up:327,href:"https://arxiv.org/abs/2610.34283",abstract:"Training a spatial VLM to answer which side an object lies on does not require it to preserve the metric displacement that determines that answer, while supervision for a distance estimate may leave categorical relations largely unconstrained. When post-training emphasizes one readout, improvements can therefore concentrate on that interface while transfer to others remains weak or even degrades; we call this observed specialization interface lock-in. ChronoReplay addresses it by replaying heterogeneous spatial supervision as chronologically ordered episodes, retaining source-native targets, a",pdfUrl:"https://arxiv.org/pdf/2610.34283",primaryCategory:"cs.CV",published:"2026-10-25T00:00:00Z"},{id:"2610.36077",title:"The Trinity:Capability-Driven Recursive Self-Improvement for Multimodal Agents",up:310,href:"https://arxiv.org/abs/2610.36077",abstract:"Multimodal intelligence can be viewed as human-guided co-evolution between worlds and agents through interaction. However, scaling this process faces two bottlenecks: constructing heterogeneous, verifiable environments is costly, and manual Harness iteration cannot keep pace with growing task diversity and complexity. A key insight is that tasks with different modalities and surface forms can share the same underlying capability requirements. We therefore introduce The Trinity, a recursive self-improvement framework coupling world generation with Harness evolution through three roles: Creator,",pdfUrl:"https://arxiv.org/pdf/2610.36077",primaryCategory:"cs.AI",published:"2026-10-26T00:00:00Z"},{id:"2610.35013",title:"Multiscale Policy Optimization for Long-Horizon LLM Agents",up:258,href:"https://arxiv.org/abs/2610.35013",abstract:"Long-horizon LLM agents interact with their environments through complete assistant turns while generating each action token by token. We observe that critic values vary primarily across turns, motivating optimization anchored at turns with finer credit allocation among tokens. We propose Multiscale Policy Optimization (MPO), combining Multiscale Advantage Estimation (MAE) and turn-level importance sampling to align credit assignment and policy updates at the turn scale. Extensive experiments across search, tool-use, and automation tasks with 4B and 30B-A3B models demonstrate consistent gains ",pdfUrl:"https://arxiv.org/pdf/2610.35013",primaryCategory:"cs.AI",published:"2026-10-26T00:00:00Z"},{id:"2610.37381",title:"PDRVLA: A Vision-Language-Action Model with Physical Dynamics Representations",up:138,href:"https://arxiv.org/abs/2610.37381",abstract:"Vision--Language--Action (VLA) models generate robot actions from visual observations and language instructions, but their understanding of physical dynamics remains limited. Video world models can capture scene dynamics, yet generating future videos introduces high latency into the control loop. We introduce PDRVLA, whose lightweight Physical Dynamics Module extracts physical tokens from vision--language features to condition action generation without online video generation. The module learns through direct prediction of future RGB, depth, and optical-flow features, with auxiliary supervisio",pdfUrl:"https://arxiv.org/pdf/2610.37381",primaryCategory:"cs.RO",published:"2026-10-27T00:00:00Z"},{id:"2610.35864",title:"VibeVideoBench: Evaluating Multimodal Agents on Code-Driven Video Generation",up:124,href:"https://arxiv.org/abs/2610.35864",abstract:"Diffusion video models produce striking clips, but they cannot reliably render an exact formula, a correct chart, a rule-consistent game or narration synchronized to on-screen events. A different route is emerging: multimodal agents that write code to render every frame and synthesize every sound. We introduce VibeVideoBench, a benchmark for evaluating agents on code-driven video generation. Its 239 self-contained tasks in English and Chinese span 12 categories, from data stories and music-driven pieces to classroom lessons and paper explainers; each asks an agent, running in its native harnes",pdfUrl:"https://arxiv.org/pdf/2610.35864",primaryCategory:"cs.CV",published:"2026-10-27T00:00:00Z"},{id:"2610.36729",title:"Hy-Nomas: Towards Free-form Interactive World Generation",up:104,href:"https://arxiv.org/abs/2610.36729",abstract:"Interactive world generation requires models to follow successive commands while preserving relevant history and action consequences. We present Hy-Nomas, a video world model with an 8B diffusion backbone that supports free-form text instructions and continuous camera control across multiple interaction turns. It generates variable-length segments conditioned on current inputs and cached history. Our central design aligns structured video captions with action-aware causal attention: descriptive context remains accessible across segments, while action instructions are restricted to their intend",pdfUrl:"https://arxiv.org/pdf/2610.36729",primaryCategory:"cs.CV",published:"2026-10-27T00:00:00Z"},{id:"2610.34073",title:"Memory Tax: Dissecting the Net Value of Agent Memory",up:95,href:"https://arxiv.org/abs/2610.34073",abstract:"Memory is increasingly used in long-horizon agents, yet the net value of building memory over direct retrieval from raw history remains largely unclear. Through a large-scale evaluation across multiple benchmarks and model backbones, we find many dedicated memory systems underperform naive RAG in many cases, indicating a negative net value. Taking RAG as a reference, we dissect the net value of memory into the gains and losses over direct retrieval, termed memory benefit and memory tax. These gains and losses arise because memory process changes how the raw information is organized and accesse",pdfUrl:"https://arxiv.org/pdf/2610.34073",primaryCategory:"cs.CL",published:"2026-10-25T00:00:00Z"},{id:"2610.37662",title:"Can Discrete Tokens Serve as Semantically Lossless Representations of Visual Signals?",up:87,href:"https://arxiv.org/abs/2610.37662",abstract:"Discrete visual tokens represent vision in a discrete form analogous to language, offering a native interface for multimodal modeling under a shared next-token prediction objective. However, quantization error is widely assumed to cause unavoidable semantic loss, fundamentally limiting the semantic fidelity of discrete visual tokens and positioning continuous visual representations as an intrinsic upper bound. Using multimodal understanding as a proxy for semantic fidelity, we revisit this assumption and find quantization error unreliable, as discrete representations with substantially larger ",pdfUrl:"https://arxiv.org/pdf/2610.37662",primaryCategory:"cs.CV",published:"2026-10-27T00:00:00Z"},{id:"2610.24520",title:"HABIT-Bench: Evaluating Habit Induction from Longitudinal Weak Evidence in Agent Memory",up:78,href:"https://arxiv.org/abs/2610.24520",abstract:"In long-term interactions with large language model (LLM) agents, users reveal habits through their choices and actions. These habits capture implicit user information that agents must infer across conversations. However, individual observations may provide only partial evidence about a habit or when it applies. Retaining past interactions alone does not ensure that agents can infer habits and apply them appropriately. We introduce HABIT-Bench to evaluate how well agent memory systems infer habits from weak evidence and apply them to later requests. We construct synthetic user histories from t",pdfUrl:"https://arxiv.org/pdf/2610.24520",primaryCategory:"cs.AI",published:"2026-10-20T00:00:00Z"},{id:"2610.32046",title:"Can Test-Time Memory Evolution Outperform Test-Time Training for Scientific Discovery?",up:51,href:"https://arxiv.org/abs/2610.32046",abstract:"Recent \\emph{test-time training} (TTT) frameworks have enabled open-weight large language models (LLMs) to outperform inference-only frameworks powered by frontier models on scientific discovery tasks. However, TTT introduces additional computational cost for online weight updates during the discovery process, making computational efficiency an important consideration when scaling to larger models. This motivates us to explore an efficient \\emph{test-time adaptation} method for scientific discovery. We introduce \\emph{Test-Time Memory Evolution} (TTME), a plug-and-play test-time adaptation met",pdfUrl:"https://arxiv.org/pdf/2610.32046",primaryCategory:"cs.AI",published:"2026-10-23T00:00:00Z"},{id:"2610.36068",title:"Rollback: Experience Backtracking in World Models for Policy Improvement",up:50,href:"https://arxiv.org/abs/2610.36068",abstract:"Action-conditioned world models offer a scalable alternative to costly real-world interaction for improving robot policies. However, existing world-model-based methods largely treat world models as forward-only surrogates of the physical environment, leaving untapped a capability no physical environment affords: rewinding to past decision points to explore counterfactual futures. We introduce Rollback, a policy improvement paradigm that turns world models from passive simulators into counterfactual engines: it rolls back to critical decision points, branches into alternative actions, and contr",pdfUrl:"https://arxiv.org/pdf/2610.36068",primaryCategory:"cs.RO",published:"2026-10-26T00:00:00Z"},{id:"2610.37341",title:"CodeCap-Bench: Can Code Serve as a Good Video Caption?",up:49,href:"https://arxiv.org/abs/2610.37341",abstract:"Video captioning aims to preserve visual information through compact descriptions, predominantly using natural language. However, precisely expressing fine-grained spatial structures and temporal dynamics in natural language often leads to lengthy and potentially ambiguous descriptions. In this work, we explore Code as Video Caption, a paradigm where executable programs serve as a complementary representation of visual content through graphical primitives, layout rules, and functions of time. To examine whether code captions effectively preserve video information, we compare them with natural ",pdfUrl:"https://arxiv.org/pdf/2610.37341",primaryCategory:"cs.CV",published:"2026-10-27T00:00:00Z"},{id:"2610.37666",title:"ThinkWorld: World Imagination Reinforces Chain-of-Dynamics Reasoning",up:46,href:"https://arxiv.org/abs/2610.37666",abstract:"Vision-Language-Action (VLA) models have made substantial progress in robotic manipulation, but their generalization remains constrained by the diversity and coverage of action-labeled robot demonstrations. Human videos provide much broader behavioral and environmental experience, while learning from them faces a fundamental trade-off between scalable data and explicit action grounding. We introduce ThinkWorld, a VLA learning framework that grounds action reasoning in world dynamics and strengthens it through reinforcement learning with world imagination. ThinkWorld represents each action thou",pdfUrl:"https://arxiv.org/pdf/2610.37666",primaryCategory:"cs.RO",published:"2026-10-27T00:00:00Z"},{id:"2610.33066",title:"OvisOCR3 Technical Report",up:28,href:"https://arxiv.org/abs/2610.33066",abstract:"We introduce OvisOCR3, a 0.8B model for a broad range of OCR-related tasks. OvisOCR3 unifies document parsing, general OCR, key information extraction (KIE), document figure captioning, and cross-page table reconstruction in a single model. We train the model on real and synthetic data through continued pretraining and use domain-balanced mid-training to balance supervision across tasks with different data volumes and response lengths. Multi-teacher on-policy distillation transfers expertise from five domain-specific 4B teachers into the shared model, followed by mixed-task reinforcement learn",pdfUrl:"https://arxiv.org/pdf/2610.33066",primaryCategory:"cs.CV",published:"2026-10-20T00:00:00Z"},{id:"2610.36456",title:"LociArt: A Unified Paradigm for Free-Style Local Video Stylization",up:28,href:"https://arxiv.org/abs/2610.36456",abstract:"Video stylization typically transforms entire scenes, while local artistic editing requires precise region--style association, spatial control, and temporal consistency. We introduce LociArt, a unified paradigm for free-style local video stylization that explicitly specifies where to stylize and what style to apply while preserving non-target content. At its core, GRNStyle builds on Generative Refinement Networks (GRN) and introduces a polar style-aware mask that embeds style identities as equal-norm directions within selected regions. Complementary representation--geometry conditioning combin",pdfUrl:"https://arxiv.org/pdf/2610.36456",primaryCategory:"cs.CV",published:"2026-10-27T00:00:00Z"},{id:"2610.26030",title:"Truncate or Not? A Scaling Study of Looped Transformers with Truncated Backpropagation",up:26,href:"https://arxiv.org/abs/2610.26030",abstract:"Looped transformers reuse a shared block of layers to increase computational depth without increasing the number of trainable parameters. They are trained with backpropagation through time (BPTT). To save training compute, BPTT is often truncated to the last few loops, but truncation yields biased gradients that may weaken the benefit of looping. In this work, we study the value of truncation in looped transformer training in a systematic way: we jointly vary model size, training tokens, and forward and backward loop counts across nearly 600 training runs and fit a unified scaling law that cap",pdfUrl:"https://arxiv.org/pdf/2610.26030",primaryCategory:"cs.LG",published:"2026-10-20T00:00:00Z"},{id:"2610.22543",title:"On the SPOT: Enhancing Speculative Decoding for Diffusion Language Models via Commit-Order Prediction",up:22,href:"https://arxiv.org/abs/2610.22543",abstract:"Diffusion language models (DLMs) promise parallel text generation, but in practice face an unresolved speed-quality trade-off. Exact decoding fills in only one masked position per model pass, while faster multi-token decoding schemes are lossy. Speculative decoding is the standard lossless acceleration for autoregressive models. However, it does not transfer directly to DLMs, which must choose both what to generate and where. We show that this order is the missing piece: the model's own predictions from the previous pass already give the right token at over $90\\%$ of positions, but not which p",pdfUrl:"https://arxiv.org/pdf/2610.22543",primaryCategory:"cs.LG",published:"2026-10-26T00:00:00Z"},{id:"2610.37037",title:"Zooming without Zooming v2: From Seeing Details to Connecting Evidence for Generalizable Multimodal Perception",up:22,href:"https://arxiv.org/abs/2610.37037",abstract:"Multimodal perception forms the foundation of multimodal intelligence. In particular, spatial perception and multimodal long-context understanding are two pivotal tasks that underpin embodied AI and multimodal agents. However, synthesizing targeted, high-quality training data for these tasks remains difficult and costly. Our key insight is that these tasks share an underlying capability, which we call connecting evidence: identifying relevant visual facts, binding them to the correct entities, recovering their relations, and composing them into an answer. Crucially, targeted training data are ",pdfUrl:"https://arxiv.org/pdf/2610.37037",primaryCategory:"cs.CV",published:"2026-10-27T00:00:00Z"},{id:"2610.33624",title:"RSI Arena: Towards Recursive Self-Improvement with Human Feedback",up:18,href:"https://arxiv.org/abs/2610.33624",abstract:"Can AI agents autonomously train useful language models and improve them using feedback from users? We introduce RSI Arena, a two-stage study of autonomous post-training as a step toward recursive self-improvement. Ten frontier models act as training agents, each starting from NVIDIA Nemotron 3.5 Lightning 30B-A3B Base. During a six-day first stage, each agent has 1,000 GPU-hours and $300 in API credit on a shared 64-GPU cluster, independently selecting data, implementing training procedures, and choosing checkpoints. We evaluate their models on 20 benchmarks and through blind human evaluation",pdfUrl:"https://arxiv.org/pdf/2610.33624",primaryCategory:"cs.CL",published:"2026-10-24T00:00:00Z"},{id:"2610.37386",title:"Channel Selection for Mixture-of-Experts Decoding Needs No Calibration Data",up:18,href:"https://arxiv.org/abs/2610.37386",abstract:"Mixture-of-Experts (MoE) models are bottlenecked by loading routed-expert weights from memory during interactive decoding at small batch sizes. Because most intermediate channels in a routed expert contribute little to any single token, channel selectors predict which channels matter and read only their weights, typically keeping channels above a threshold calibrated on offline data. We show that channel selection needs no calibration data. First, a calibrated threshold does not fix how much a selector reads, because the number of channels passing it varies across inputs; Prox with thresholds ",pdfUrl:"https://arxiv.org/pdf/2610.37386",primaryCategory:"cs.LG",published:"2026-10-27T00:00:00Z"},{id:"2610.35724",title:"MatAnyone-E: Sparse Memory Propagation for Efficient High-Resolution Video Matting",up:16,href:"https://arxiv.org/abs/2610.35724",abstract:"High-resolution video matting requires preserving fine details, such as hair strands and soft transparency, while maintaining consistency across frames. Memory-based methods achieve strong matting quality by matching current-frame features with information stored from earlier frames, but this process becomes increasingly costly as resolution grows. We present MatAnyone-E, an efficient extension of MatAnyone 2 that focuses computation where it is most needed. Our approach first performs low-resolution propagation to identify uncertain regions that require closer inspection and the memory candid",pdfUrl:"https://arxiv.org/pdf/2610.35724",primaryCategory:"cs.CV",published:"2026-10-26T00:00:00Z"},{id:"2610.34491",title:"What Effort Level Should I Choose? On the Economics of Reasoning Effort in LLM Agents",up:15,href:"https://arxiv.org/abs/2610.34491",abstract:"Generative models increasingly expose a reasoning effort setting that lets users scale inference-time compute, trading higher cost for potentially improved performance. Users must choose an effort level before knowing whether extra reasoning will help, and even a successful run does not reveal whether the effort purchased was necessary. Reasoning effort is therefore a credence good: buyers observe the outcome but cannot assess the marginal value of the computation they paid for. In this work, we measure the counterfactual effect of effort levels on both proprietary and open-weight models on fo",pdfUrl:"https://arxiv.org/pdf/2610.34491",primaryCategory:"cs.AI",published:"2026-10-25T00:00:00Z"},{id:"2610.35962",title:"h1: A Taste of the Bitter Lesson in Automated Theorem Proving",up:12,href:"https://arxiv.org/abs/2610.35962",abstract:"While progress in informal mathematics has come largely from scaling the chain-of-thought and agentic reasoning of frontier language models, formal theorem proving has increasingly relied on human-designed workflows around these models, such as planning, decomposition, and orchestrating specialized provers. This raises a bitter-lesson question: can a simple agentic loop that scales test-time compute match these workflows? The answer matters as formal verification must scale to keep up with frontier models producing research mathematics, yet new workflows rarely settle it, as their gains are of",pdfUrl:"https://arxiv.org/pdf/2610.35962",primaryCategory:"cs.LG",published:"2026-10-25T00:00:00Z"},{id:"2610.35439",title:"Omni-InteractScope: Benchmarking Proactive and Agentic Interaction in Continuous Omnimodal Streams",up:11,href:"https://arxiv.org/abs/2610.35439",abstract:"Omnimodal large language models (Omni-LLMs) are increasingly expected to assist users while observing continuous audiovisual streams. However, existing evaluations provide limited insight into how reliably these models connect stream evidence and user needs to timely, sustained interventions. We introduce \\textbf{Omni-InteractScope}, a benchmark of 1,479 human-annotated, cross-reviewed interactions with 1,790 temporal targets across eight task groups. It links input modalities, event triggers, intervention types, and user needs, covering event-timed tool invocation and query-free assistance al",pdfUrl:"https://arxiv.org/pdf/2610.35439",primaryCategory:"cs.AI",published:"2026-10-26T00:00:00Z"},{id:"W7171617880",title:"Machine-Speed Intrusion: A Detection Engineering Analysis of the July 2026 Hugging Face Agent Campaign",up:0,href:"https://doi.org/10.5281/zenodo.21686546",doi:"https://doi.org/10.5281/zenodo.21686546",year:2026,openalexId:"https://openalex.org/W7171617880"},{id:"W7171936549",title:"Could a Capability-Security Architecture Have Contained the July 2026 OpenAI-Hugging Face Agentic Exploit Chain?",up:0,href:"https://doi.org/10.5281/zenodo.21715175",doi:"https://doi.org/10.5281/zenodo.21715175",year:2026,openalexId:"https://openalex.org/W7171936549"},{id:"W7203931864",title:"hf-data-agent: a Hugging Face backed RAG data agent",up:0,href:"https://doi.org/10.5281/zenodo.22043399",doi:"https://doi.org/10.5281/zenodo.22043399",year:2026,openalexId:"https://openalex.org/W7203931864"}]}}]);